# Attempt sliding window search for likely target objects, and display the original image for manual inspection.
try:
    print("Displaying the original image for manual inspection:")
    display(image_1)
except Exception as e:
    print("Could not display original image:", e)

search_terms = ["red ball", "red sphere", "brown object", "brown ball", "metal sphere", "metallic sphere", "ball", "sphere"]
try:
    print("\nRunning sliding_window_detection for candidate terms...")
    possible_patches, possible_boxes = sliding_window_detection(image_1, search_terms)
    if not possible_patches:
        print("No patches returned by sliding_window_detection.")
    else:
        print(f"Received {len(possible_patches)} patch(es) from sliding_window_detection. Displaying them:")
        for i, patch in enumerate(possible_patches):
            print(f"\nPatch {i+1}:")
            display(patch.annotated_image)
            # print boxes detected within this patch (if provided)
            try:
                print("Boxes in this patch:", possible_boxes[i])
            except Exception:
                pass
except Exception as e:
    print("sliding_window_detection failed with error:", e)

print("\nIf the automated tools did not find/segment objects, please inspect the displayed original image and tell me\nhow many objects remain after subtracting all big red metallic spheres and all big brown matte things, or\nallow me to try another detection/thresholding strategy.")
